import {pads} from './topic.js';
export const die=()=>`<rect x="-13" y="-14" width="26" height="28" rx="1" class="silicon outline"/><path d="M-5-7H5V7H-5Z M-5 0H5 M0-7V7" fill="none" stroke="#67899f" stroke-width=".6"/>${pads.map(p=>`<rect x="${p.pad[0]-1.7}" y="${p.pad[1]-1.7}" width="3.4" height="3.4" fill="#e9d6a4" stroke="#70552f" stroke-width=".5"/>`).join('')}`;
export const wirePath=p=>`M ${p.pad} Q ${p.side*17},${p.finger[1]*.82} ${p.finger}`;
export const fingers=()=>pads.map(p=>`<path class="metal outline finger" d="M${p.side*24} ${p.finger[1]-4}H${p.side*56}V${p.finger[1]+4}H${p.side*24}Z"/>`).join('');
export const temporary=()=>`<path class="metal outline frame-rail" fill-rule="evenodd" d="M-61-59H61V59H-61Z M-55-53V53H55V-53Z"/><path class="metal outline support" d="M-2-56H2V-18H-2Z M-2 18H2V56H-2Z"/>${[-1,1].flatMap(side=>[-18,0,18].map((y,i)=>`<rect data-cut="${(side<0?0:3)+i}" x="${side*44-2}" y="${y-5}" width="4" height="10" class="metal outline dambar"/>`)).join('')}`;
export function assembly(prefix=''){return `<g id="${prefix}fingers">${fingers()}</g><g id="${prefix}temporary">${temporary()}</g><rect id="${prefix}paddle" x="-16" y="-18" width="32" height="36" class="metal outline"/><rect id="${prefix}glue" x="-14.6" y="-15.6" width="29.2" height="31.2" rx="3" fill="var(--adhesive)" stroke="#8b7e69" stroke-width="1"/><g id="${prefix}inner-die">${die()}</g><g id="${prefix}wires">${pads.map((p,i)=>`<g><path data-wire="${i}" d="${wirePath(p)}" class="wire" pathLength="1" stroke-dasharray="1" stroke-dashoffset="1"/><circle data-bond="${i}" cx="${p.pad[0]}" cy="${p.pad[1]}" r="1.8" fill="var(--wire)"/><circle data-end="${i}" cx="${p.finger[0]}" cy="${p.finger[1]}" r="1.8" fill="var(--wire)"/></g>`).join('')}</g><g clip-path="url(#${prefix}body-clip)"><rect id="${prefix}body" x="-30" y="-38" width="60" height="0" class="emc"/><circle id="${prefix}pin-one" cx="-19" cy="-27" r="3" fill="#93a0a7"/></g>`;}
export function wafer(prefix=''){return `<circle r="80" fill="none" stroke="#b3b9bd" stroke-width="8"/><circle r="75" class="tape"/><g clip-path="url(#${prefix}wafer-clip)"><circle r="65" class="silicon outline"/><path d="M-39-65V65M-13-65V65M13-65V65M39-65V65M-65-39H65M-65-13H65M-65 13H65M-65 39H65" stroke="#69899d" stroke-width=".65" fill="none"/><path d="M-5-65L0-59L5-65" fill="#e0e9ed" stroke="#59636a" stroke-width="1"/>${[-39,-13,13,39].map((v,i)=>`<path data-saw="${i}" d="M${v}-65V65" stroke="#e0e9ed" stroke-width="3" pathLength="1" stroke-dasharray="1"/>`).join('')}${[-39,-13,13,39].map((v,i)=>`<path data-saw="${i+4}" d="M-65 ${v}H65" stroke="#e0e9ed" stroke-width="3" pathLength="1" stroke-dasharray="1"/>`).join('')}<rect id="${prefix}hole" x="-13" y="-14" width="26" height="28" fill="#e0e9ed"/></g>`;}
export const defs=(prefix='')=>`<clipPath id="${prefix}wafer-clip"><circle r="65"/></clipPath><clipPath id="${prefix}body-clip"><rect x="-30" y="-38" width="60" height="76" rx="5"/></clipPath>`;
export function detailArt(stage){
 let top='';
 if(stage===0)top=`<g transform="translate(160 100)">${wafer('detail-')}</g>`;
 else top=`<g transform="translate(160 85)">${assembly('detail-')}</g>`;
 const side=stage===2?`<text x="20" y="177">側視示意 · 金線具有線弧高度</text><path d="M65 225H255" class="fine"/><path d="M90 223V207H120V223 M213 223V214H244V223" class="metal outline"/><rect x="94" y="199" width="22" height="8" class="silicon outline"/><path d="M108 199Q158 153 225 214" class="wire"/>`:stage===3?`<text x="20" y="177">剖視示意 · 內部結構持續保留</text><path d="M70 233V198Q70 188 80 188H240Q250 188 250 198V233Z" class="emc"/><path d="M50 225H126 M194 225H270" stroke="#b3b9bd" stroke-width="5"/><rect x="133" y="216" width="54" height="5" fill="#b3b9bd"/><rect x="142" y="205" width="36" height="10" class="silicon"/><path d="M146 205Q116 180 95 225M174 205Q204 180 225 225" stroke="#dab87e" fill="none" stroke-width="2"/>`:stage===4?`<text x="20" y="177">側視示意 · gull-wing 外腳</text><rect x="115" y="193" width="90" height="30" rx="3" class="emc"/><path d="M115 205H98L86 229H65M205 205H222L234 229H255" stroke="#59636a" stroke-width="6" fill="none" stroke-linejoin="round"/><path d="M55 235H265" class="fine"/>`:'';
 return `<svg viewBox="0 0 320 ${side?255:190}" role="img" aria-label="${stage===0?'切割後仍在膠帶上的晶圓':'本站完成狀態放大示意'}"><defs>${defs('detail-')}</defs>${top}${side}</svg>`;
}
